/* Turn Around is a native, editable TiddlyWiki tiddler.
   Its cinematic production stylesheet also changes the story river.
   Preserve the native sidebar toggle and tiddler toolbars without changing
   the separate opt-in fullscreen audience player.

   TiddlyWiki leaves .tc-sidebar-scrollable in the DOM when collapsed.
   Use the state-driven PageTemplate class below, not :has() on its existence. */
@media (min-width: 960px) {
  body.tc-body .tc-story-river {
    box-sizing: border-box;
    position: relative;
    left: 0 !important;
    width: auto !important;
    max-width: none !important;
    margin: 0 280px 0 24px !important;
    padding: 42px !important;
  }
  /* When the native sidebar is collapsed, fill the available page width. */
  body.tc-body .plato-sidebar-closed .tc-story-river,
  body.tc-body.plato-sidebar-closed .tc-story-river {
    margin-right: 24px !important;
  }
}
.tc-tiddler-frame[data-tiddler-title="Turn Around"] .tc-titlebar,
.tc-tiddler-frame[data-tiddler-title="Turn Around"] .tc-tags-wrapper {
  display: block !important;
}
